/// <summary>
///     The <c>SalesLineBackOrderFrm_Extension</c> class is the extension for <c>SalesLineBackOrder</c>
/// </summary>
[ExtensionOf(FormStr(SalesLineBackOrder))]
final class SalesLineBackOrderFrm_Extension
{
    public InventSiteId        frmInitialInventSiteId;
    public UserId              frmUserId;
    public HcmWorkerRecId      frmHcmWorkerRecId;
    public HCMWorker           frmHCMWorker;
    public AVAWorkerInventSite frmAVAWorkerInventSite;

}

Method.Source:
/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    frmUserId               = curUserId();
    frmHcmWorkerRecId       = HcmWorkerLookup::currentWorker();
    frmHCMWorker            = HCMWorker::find(frmHcmWorkerRecId);
    frmAVAWorkerInventSite  = AVAWorkerInventSite::find(frmHCMWorker.PersonnelNumber);

    frmInitialInventSiteId = frmAVAWorkerInventSite.InventSiteId;

    next init();

    GridFilterInventSiteId.text(frmInitialInventSiteId);

    this.replaceSortOrder();
    this.addFilterPaneRanges();

    GridFilterInventSiteId.enabled(true);
}

/// <summary>
///     AVA <c>addFilterPaneRanges</c> method.
/// </summary>
public void addFilterPaneRanges()
{
    QueryBuildDataSource salesTableQBDS;

    salesTableQBDS = SalesTable_DS.query().dataSourceName(SalesTable_DS.name());

    SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, InventSiteId));
}

/// <summary>
///     AVA <c>replaceSortOrder</c> method.
/// </summary>
public void replaceSortOrder()
{
    QueryBuildDataSource salesLineQBDS;

    salesLineQBDS = SalesLine_DS.query().dataSourceName(SalesLine_DS.name());
    salesLineQBDS.clearSortIndex();
    salesLineQBDS.addSortField(fieldNum(SalesLine, SalesId),SortOrder::Ascending);
    salesLineQBDS.addSortField(fieldNum(SalesLine, LineNum),SortOrder::Ascending);
}
